#include "hunt_pounce.h"
#include "stream.h"
#include "pounce.h"
#include "sequence.h"
#include "technique_common.h"
#include "../flow/phase_controller.h"
#include <algorithm>
namespace speed {
namespace {const CanisHuntPounceDefinition &rule(const ContentBundle &c,uint32_t definition) {return *std::find_if(c.canis_hunt_pounces.begin(),c.canis_hunt_pounces.end(),[&](const auto &v){return v.technique==definition;});}}
bool CanisHuntPounce::ready(const RunRuntime &r,EnemyHandle actor,uint32_t definition) {const auto *b=PhaseController::find(r,actor);return b && b->phase==1 && CanisStream::ready(r,actor,rule(*r.content,definition).stream);}
double CanisHuntPounce::attack_length(const RunRuntime &r,EnemyHandle actor,uint32_t definition) {const auto &p=rule(*r.content,definition);const auto *b=PhaseController::find(r,actor);const auto &stream=*std::find_if(r.content->canis_streams.begin(),r.content->canis_streams.end(),[&](const auto &v){return v.technique==p.stream;});const auto &jump=r.content->boss_techniques[p.pounce-1];return r.content->boss_techniques[p.stream-1].warn+std::max(0,int(b?b->canis.led.size():0)-1)*stream.interval+stream.each_warn+p.gap+jump.warn+CanisPounce::flight_time(r,p.pounce)+0.05;}
void CanisHuntPounce::begin(RunRuntime &r,TechniqueState &t) {t.detail=CanisHuntPounceState{};auto &v=std::get<CanisHuntPounceState>(t.detail);CanisTechnique::remember_usage(r,t,"stream");CanisStream::start(r,t,v.stream,rule(*r.content,t.definition).stream);}
void CanisHuntPounce::step(RunRuntime &r,TechniqueState &t,double dt) {auto &v=std::get<CanisHuntPounceState>(t.detail);const auto &p=rule(*r.content,t.definition);const auto *b=PhaseController::find(r,t.actor);if (!b) {t.stage=TechniqueStage::Failed;return;}if (t.stage==TechniqueStage::Recovery) {r.state.enemies[t.actor.slot].vel={};t.remaining=std::max(0.0,t.remaining-dt);if (t.remaining<=0) t.stage=TechniqueStage::Finished;return;}CanisStream::advance(r,t,v.stream,dt,true);if (v.combo_pending && v.stream.sent && b->clock>=v.stream.last_launch+p.gap) {v.combo_pending=false;v.jumping=true;CanisTechnique::remember_usage(r,t,"pounce");CanisPounce::start(r,t,v.jump,p.pounce,1);}if (v.jumping && CanisPounce::advance(r,t,v.jump,dt)) {t.stage=TechniqueStage::Recovery;t.remaining=r.content->boss_techniques[p.pounce-1].recover;t.locked=false;r.state.enemies[t.actor.slot].vel={};CanisTechnique::cue(r,t,"recovery_started");}}
void CanisHuntPounce::cancel(RunRuntime &r,TechniqueState &t) {auto &v=std::get<CanisHuntPounceState>(t.detail);CanisSequence::cancel(r,t,v.stream.sequence);v.combo_pending=false;}
bool CanisHuntPounce::validate(const TechniqueState &t,const ContentBundle &c) {const auto *v=std::get_if<CanisHuntPounceState>(&t.detail);return v && CanisStream::validate(v->stream,c) && (!v->jumping || CanisPounce::validate(v->jump,c)) && !(v->combo_pending && v->jumping);}
double CanisHuntPounce::progress(const RunRuntime &r,const TechniqueState &t) {const auto &v=std::get<CanisHuntPounceState>(t.detail);if (v.jumping) return CanisPounce::progress(v.jump);const auto *b=PhaseController::find(r,t.actor);return b?std::clamp((b->clock-v.stream.started)/std::max(0.001,r.content->boss_techniques[v.stream.definition-1].warn),0.0,1.0):0;}
godot::Dictionary CanisHuntPounce::snapshot(const RunRuntime &r,const TechniqueState &t) {const auto &v=std::get<CanisHuntPounceState>(t.detail);auto out=CanisStream::snapshot(r,t.actor,v.stream);out["jumping"]=v.jumping;out["combo_pending"]=v.combo_pending;out["jump_active"]=v.jump.jumping;out["jump_done"]=v.jump.done;out["jump_age"]=v.jump.stage_time;out["left"]=v.jump.left;if (v.jumping) out["pounce_motion"]=CanisPounce::motion_snapshot(r,v.jump);out["windup_progress"]=progress(r,t);out["crouch"]=v.jumping?CanisPounce::progress(v.jump):0;out["stretch"]=v.jumping?(v.jump.jumping?1.15:1.0-CanisPounce::progress(v.jump)*0.15):1.0;return out;}
}
